package edu.comillas.icai.gitt.pat.spring.jpa3.service;

import edu.comillas.icai.gitt.pat.spring.jpa3.entity.Pista;
import edu.comillas.icai.gitt.pat.spring.jpa3.repos.PistaRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
public class PistaService {
    private static final Logger log = LoggerFactory.getLogger(PistaService.class);
    private final PistaRepository pistaRepository;

    public PistaService(PistaRepository pistaRepository) {
        this.pistaRepository = pistaRepository;
    }

    public Pista guardarPista(Pista pista) {
        log.info("Guardando nueva pista: {}", pista.nombre);
        return pistaRepository.save(pista);
    }

    public List<Pista> listarPistasActivas() {
        log.debug("Listando todas las pistas del sistema");
        return pistaRepository.findAll().stream()
                .filter(p -> p.activa)
                .toList();
    }
}

package edu.comillas.icai.gitt.pat.spring.jpa3.service;

import edu.comillas.icai.gitt.pat.spring.jpa3.entity.Pista;
import edu.comillas.icai.gitt.pat.spring.jpa3.repos.PistaRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.util.List;

@Service
public class PistaService {
    private static final Logger log = LoggerFactory.getLogger(PistaService.class);

    @Autowired
    private PistaRepository pistaRepository;

    @Transactional
    public Pista crearPista(Pista pista) {
        log.info("Creando nueva pista: {}", pista.nombre);
        return pistaRepository.save(pista);
    }

    @Transactional
    public Pista guardarPista(Pista pista) {
        return crearPista(pista);
    }

    public List<Pista> listarPistas() {
        log.debug("Listando todas las pistas del sistema");
        return pistaRepository.findAll();
    }

    public List<Pista> listarPistasActivas() {
        log.debug("Listando todas las pistas activas del sistema");
        return pistaRepository.findAll().stream()
                .filter(p -> p.activa)
                .toList();
    }

    public Pista buscarPista(Long id) {
        log.debug("Buscando pista por ID: {}", id);
        return pistaRepository.findById(id)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "Pista no encontrada"
                ));
    }

    @Transactional
    public Pista actualizarPista(Long id, Pista cambios) {
        log.debug("Actualizando pista ID: {}", id);
        Pista pista = buscarPista(id);

        if (cambios.nombre != null && !cambios.nombre.isBlank()) {
            pista.nombre = cambios.nombre;
        }
        if (cambios.tipo != null && !cambios.tipo.isBlank()) {
            pista.tipo = cambios.tipo;
        }
        if (cambios.precio != null) {
            pista.precio = cambios.precio;
        }
        if (cambios.activa != null) {
            pista.activa = cambios.activa;
        }

        log.info("Pista ID {} actualizada correctamente", id);
        return pistaRepository.save(pista);
    }

    @Transactional
    public void borrarPista(Long id) {
        log.debug("Eliminando pista ID: {}", id);
        Pista pista = buscarPista(id);
        pistaRepository.delete(pista);
        log.info("Pista ID {} eliminada correctamente", id);
    }
}

package edu.comillas.icai.gitt.pat.spring.jpa3.service;

import edu.comillas.icai.gitt.pat.spring.jpa3.entity.EstadoReserva;
import edu.comillas.icai.gitt.pat.spring.jpa3.entity.Reserva;
import edu.comillas.icai.gitt.pat.spring.jpa3.repos.ReservaRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.time.LocalDateTime;
import java.util.List;

@Service
public class ReservaService {
    private static final Logger log = LoggerFactory.getLogger(ReservaService.class);
    private final ReservaRepository reservaRepository;
    private final EmailService emailService;

    public ReservaService(ReservaRepository reservaRepository, EmailService emailService) {
        this.reservaRepository = reservaRepository;
        this.emailService = emailService;
    }

    public Reserva crearReserva(Reserva reserva) {
        log.debug("Iniciando proceso de reserva para usuario: {}", reserva.usuario.email);

        // Lógica de negocio de la entidad
        reserva.calcularHoraFin();
        reserva.estado = EstadoReserva.ACTIVA;
        reserva.fechaCreacion = LocalDateTime.now();

        try {
            Reserva guardada = reservaRepository.save(reserva);
            log.info("Reserva ID {} creada con éxito", guardada.idReserva);

            // Notificar por email
            emailService.enviarConfirmacion(guardada);
            return guardada;
        } catch (Exception e) {
            log.error("Error crítico al guardar la reserva: {}", e.getMessage());
            throw e;
        }
    }

    public List<Reserva> obtenerReservasPorUsuario(Long idUsuario) {
        log.debug("Consultando reservas del usuario ID: {}", idUsuario);
        return reservaRepository.findByUsuario_Id(idUsuario);
    }

}

package edu.comillas.icai.gitt.pat.spring.jpa3.service;

import edu.comillas.icai.gitt.pat.spring.jpa3.entity.EstadoReserva;
import edu.comillas.icai.gitt.pat.spring.jpa3.entity.Reserva;
import edu.comillas.icai.gitt.pat.spring.jpa3.repos.ReservaRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;
import java.util.List;

@Service
public class ReservaService {
    private static final Logger log = LoggerFactory.getLogger(ReservaService.class);

    @Autowired
    private ReservaRepository reservaRepository;

    @Autowired
    private EmailService emailService;

    @Transactional
    public Reserva crearReserva(Reserva reserva) {
        log.debug("Iniciando proceso de reserva para usuario: {}", reserva.usuario.email);

        // Lógica de negocio de la entidad
        reserva.calcularHoraFin();
        reserva.estado = EstadoReserva.ACTIVA;
        reserva.fechaCreacion = LocalDateTime.now();

        try {
            Reserva guardada = reservaRepository.save(reserva);
            log.info("Reserva ID {} creada con éxito", guardada.idReserva);

            // Notificar por email
            emailService.enviarConfirmacion(guardada);
            return guardada;
        } catch (Exception e) {
            log.error("Error crítico al guardar la reserva: {}", e.getMessage());
            throw e;
        }
    }

    public List<Reserva> obtenerReservasPorUsuario(Long idUsuario) {
        log.debug("Consultando reservas del usuario ID: {}", idUsuario);
        return reservaRepository.findByUsuario_Id(idUsuario);
    }

    @Transactional
    public Reserva modificarReserva(Reserva cambios) {
        log.debug("Modificando reserva ID: {}", cambios.idReserva);
        return reservaRepository.save(cambios);
    }

    @Transactional
    public void cancelarReserva(Long id) {
        log.debug("Cancelando reserva ID: {}", id);
        Reserva reserva = reservaRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Reserva no encontrada"));
        reserva.estado = EstadoReserva.CANCELADA;
        reservaRepository.save(reserva);
        log.info("Reserva ID {} cancelada", id);
    }

    public List<Reserva> listarTodas() {
        log.debug("Listando todas las reservas");
        return reservaRepository.findAll();
    }

    public Reserva obtenerPorId(Long id) {
        log.debug("Obteniendo reserva ID: {}", id);
        return reservaRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Reserva no encontrada"));
    }
}

package edu.comillas.icai.gitt.pat.spring.jpa3.service;


import edu.comillas.icai.gitt.pat.spring.jpa3.entity.Usuario;
import edu.comillas.icai.gitt.pat.spring.jpa3.repos.UsuarioRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.util.List;
import java.util.Optional;

@Service
public class UsuarioService {
    private static final Logger log = LoggerFactory.getLogger(UsuarioService.class);
    private final UsuarioRepository usuarioRepository;

    public UsuarioService(UsuarioRepository usuarioRepository) {
        this.usuarioRepository = usuarioRepository;
    }

    public Usuario crearUsuario(Usuario usuario) {
        log.debug("Intentando crear usuario con email: {}", usuario.email);
        if (usuarioRepository.findByEmail(usuario.email).isPresent()) {
            log.error("Error al crear usuario: El email {} ya existe", usuario.email);
            throw new RuntimeException("El usuario ya existe");
        }
        log.info("Usuario {} creado correctamente", usuario.nombre);
        return usuarioRepository.save(usuario);
    }

    public Optional<Usuario> buscarPorEmail(String email) {
        log.debug("Buscando usuario por email: {}", email);
        return usuarioRepository.findByEmail(email);
    }

    public List<Usuario> listarTodos() {
        return usuarioRepository.findAll();
    }
}

package edu.comillas.icai.gitt.pat.spring.jpa3.service;

import edu.comillas.icai.gitt.pat.spring.jpa3.entity.Usuario;
import edu.comillas.icai.gitt.pat.spring.jpa3.repos.UsuarioRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.util.List;
import java.util.Optional;

@Service
public class UsuarioService {
    private static final Logger log = LoggerFactory.getLogger(UsuarioService.class);

    @Autowired
    private UsuarioRepository usuarioRepository;

    @Transactional
    public Usuario registrar(Usuario usuario) {
        log.debug("Intentando registrar usuario con email: {}", usuario.email);
        if (usuarioRepository.findByEmail(usuario.email).isPresent()) {
            log.error("Error al registrar usuario: El email {} ya existe", usuario.email);
            throw new RuntimeException("El usuario ya existe");
        }
        log.info("Usuario {} registrado correctamente", usuario.nombre);
        return usuarioRepository.save(usuario);
    }

    @Transactional
    public Usuario crearUsuario(Usuario usuario) {
        return registrar(usuario);
    }

    public Usuario obtenerPorEmail(String email) {
        log.debug("Buscando usuario por email: {}", email);
        return usuarioRepository.findByEmail(email)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "Usuario no encontrado"
                ));
    }

    public Optional<Usuario> buscarPorEmail(String email) {
        log.debug("Buscando usuario por email: {}", email);
        return usuarioRepository.findByEmail(email);
    }

    public Usuario obtenerPorId(Long id) {
        log.debug("Buscando usuario por ID: {}", id);
        return usuarioRepository.findById(id)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "Usuario no encontrado"
                ));
    }

    public List<Usuario> listar() {
        log.debug("Listando todos los usuarios");
        return usuarioRepository.findAll();
    }

    public List<Usuario> listarTodos() {
        return listar();
    }

    @Transactional
    public Usuario patch(Long id, Usuario cambios) {
        log.debug("Actualizando usuario ID: {}", id);
        Usuario usuario = obtenerPorId(id);

        if (cambios.nombre != null && !cambios.nombre.isBlank()) {
            usuario.nombre = cambios.nombre;
        }
        if (cambios.apellidos != null && !cambios.apellidos.isBlank()) {
            usuario.apellidos = cambios.apellidos;
        }
        if (cambios.telefono != null && !cambios.telefono.isBlank()) {
            usuario.telefono = cambios.telefono;
        }

        log.info("Usuario ID {} actualizado correctamente", id);
        return usuarioRepository.save(usuario);
    }

    public boolean esDueno(Long id, String email) {
        log.debug("Verificando si el usuario con email {} es dueño del usuario ID {}", email, id);
        Optional<Usuario> usuario = usuarioRepository.findByEmail(email);
        if (usuario.isEmpty()) {
            return false;
        }
        return usuario.get().id.equals(id);
    }
}
